    %{}
    |> Kuaa.Encode.put_optional("state", params.state)
  end
end

defmodule Kuaa.WebhookRequest do
  @moduledoc """
  

  Build it with `new/1` from a keyword list or a map; an optional field left
  out is left out of the JSON.
  """

  @enforce_keys [:events, :name, :url]
  defstruct [:events, :name, :url]

  @typedoc """
  * `events`: The events the endpoint receives.
  * `name`: What the tenant calls the endpoint.
  * `url`: The https:// address the deliveries go to. An address without TLS, with a user or a password, or whose host is or resolves to a loopback, private, link-local, metadata or shared (100.64.0.0/10) address is refused with 422; every attempt checks the address again as it connects.
  """
  @type t :: %__MODULE__{
          events: [String.t()],
          name: String.t(),
          url: String.t()
        }

  @doc "The params as they are, or built from a keyword list or a map with atom keys."
  @spec new(t() | keyword() | map()) :: t()
  def new(%__MODULE__{} = params), do: params
  def new(fields), do: struct!(__MODULE__, fields)

  @doc "The body as the API reads it, from the params or what `new/1` builds them from."
  @spec to_map(t() | keyword() | map()) :: %{optional(String.t()) => term()}
  def to_map(params) do
    params = new(params)

    %{"events" => Kuaa.Encode.value(params.events), "name" => params.name, "url" => params.url}
  end
end
